package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.ApplicationSessionIdentity;import org.junit.jupiter.api.*;import org.springframework.beans.factory.ObjectProvider;import java.util.function.Function;import java.nio.file.*;import java.nio.file.attribute.PosixFilePermissions;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Actual service, immutable intent and transport; acceptance and final registry are explicit authority boundaries, not professional execution fixtures. */
class PublicationServiceFlowTest {
 FormalAgentPublicationObjectLedgerTest f;EnterpriseAccess access;ApplicationSessionIdentity.Verified subject;FormalAgentAcceptanceStore acceptances;FormalAgentPublicationAuthorization authority;FormalAgentPublicationRegistration registrations;AgentPublicationAuthority published;PublicationEvidenceRevalidation evidence;ObjectProvider<PublicationEvidenceRevalidation> ep;ObjectProvider<RuntimeObjectTransport> tp;FormalAgentPublicationService service;S3ObjectWriter writer;Path dir;
 @BeforeEach void setup()throws Exception{
 f=new FormalAgentPublicationObjectLedgerTest();access=mock(EnterpriseAccess.class);subject=mock(ApplicationSessionIdentity.Verified.class);
 when(access.execute(eq(subject),any())).thenAnswer(i->{f.begin();try{return ((Function<EnterpriseAccess.Admission,Object>)i.getArgument(1)).apply(f.a);}finally{f.end();}});
 acceptances=mock(FormalAgentAcceptanceStore.class);authority=mock(FormalAgentPublicationAuthorization.class);registrations=mock(FormalAgentPublicationRegistration.class);published=mock(AgentPublicationAuthority.class);evidence=mock(PublicationEvidenceRevalidation.class);ep=mock(ObjectProvider.class);tp=mock(ObjectProvider.class);when(ep.getIfAvailable()).thenReturn(evidence);
 var loaded=mock(FormalAgentAcceptanceStore.Loaded.class);when(loaded.content()).thenReturn(f.json.object());when(acceptances.metadata(eq(f.a),any(),eq("AGENT_PUBLICATION"))).thenReturn(loaded);
 var prepared=mock(PublicationEvidenceRevalidation.Prepared.class);when(evidence.prepare(eq(subject),eq("1"),any(),eq(false))).thenReturn(prepared);when(authority.require(eq(f.a),any(),eq(true),eq(false),eq(prepared))).thenReturn(f.proof);
 dir=Files.createTempDirectory("publication-flow-",PosixFilePermissions.asFileAttribute(PosixFilePermissions.fromString("rwx------")));writer=mock(S3ObjectWriter.class);
 when(writer.writeVerified(any(),any(),any())).thenAnswer(i->{var intent=(S3ObjectWriter.WriteIntent)i.getArgument(0);return new InterfaceProtocol.ObjectRef(intent.objectKey(),"actual-version",intent.sha256(),intent.sizeBytes(),intent.mediaType());});
 when(writer.recoverVerified(any(),any())).thenAnswer(i->{var intent=(S3ObjectWriter.WriteIntent)i.getArgument(0);return new InterfaceProtocol.ObjectRef(intent.objectKey(),"actual-version",intent.sha256(),intent.sizeBytes(),intent.mediaType());});
 when(tp.getIfAvailable()).thenReturn(new RuntimeObjectTransport(()->writer,dir,16*1024*1024));
 when(registrations.finish(eq(f.a),any(),any(),eq(f.proof))).thenAnswer(i->{var a=(FormalAgentPublicationObjectLedger.Attempt)i.getArgument(1);var transfer=(RuntimeObjectTransport.VerifiedTransfer)i.getArgument(2);assertSame(a,transfer.originalAttempt());return f.json.object().put("operation_id",f.row.operation()).put("release_id",f.row.release()).put("artifact_id",f.row.artifact()).put("manifest_sha256",f.row.payloadHash()).put("request_body_sha256",f.formal.hash(f.request));});
 service=new FormalAgentPublicationService(access,f.formal,f.json,acceptances,authority,f.ledger,registrations,published,ep,tp);
 }
 @AfterEach void cleanup()throws Exception{try(var files=Files.list(dir)){assertEquals(0,files.count());}Files.delete(dir);}
 byte[] body()throws Exception{return f.formal.canonical(f.request).getBytes(java.nio.charset.StandardCharsets.UTF_8);}
 @Test void actualButtonObtainsPrivateTransferBeforeFinalRegistration()throws Exception{var r=service.publish(subject,"1",f.key,body());assertEquals("COMPLETED",r.path("state").asText());assertEquals(f.formal.hash(f.request),r.path("request_body_sha256").asText());verify(writer).writeVerified(any(),any(),any());verify(registrations).finish(eq(f.a),any(),any(),eq(f.proof));assertEquals(1,f.attempts);}
 @Test void retryAfterIndeterminateRegistrationRecoversOriginalObjectOnly()throws Exception{doThrow(new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE)).when(registrations).finish(eq(f.a),any(),any(),eq(f.proof));assertThrows(Exception.class,()->service.publish(subject,"1",f.key,body()));assertThrows(Exception.class,()->service.publish(subject,"1",f.key,body()));verify(writer,times(1)).writeVerified(any(),any(),any());verify(writer,times(1)).recoverVerified(any(),any());assertEquals(1,f.attempts);}
 @Test void processingReadDoesNotTransferOrFinish()throws Exception{service.publish(subject,"1",f.key,body());clearInvocations(writer,registrations,evidence);var r=service.receipt(subject,"1",f.key);assertEquals("PROCESSING",r.path("state").asText());verifyNoInteractions(writer,registrations,evidence);}
 @Test void readonlyProcessingCannotTrustDeletedAttempt()throws Exception{service.publish(subject,"1",f.key,body());f.attempted=null;clearInvocations(writer,registrations);assertThrows(Exception.class,()->service.receipt(subject,"1",f.key));verifyNoInteractions(writer,registrations);}
 @Test void missingActualProfessionalAdapterCreatesNoIntent()throws Exception{when(ep.getIfAvailable()).thenReturn(null);assertThrows(Exception.class,()->service.publish(subject,"1",f.key,body()));assertNull(f.row);verifyNoInteractions(writer,registrations);}
 @Test void changedOriginalBodyCannotReusePhysicalWrite()throws Exception{service.publish(subject,"1",f.key,body());((com.fasterxml.jackson.databind.node.ObjectNode)f.request).put("reason","Different reason");assertThrows(Exception.class,()->service.publish(subject,"1",f.key,body()));verify(writer,times(1)).writeVerified(any(),any(),any());assertEquals(1,f.attempts);}
}
